# [ src/menus/0000_hardcoded_mb1011/morale_report.py:L1-L63 ] morale_report
("morale_report", mnf_enable_hot_keys,
   "{s1}",
   "none",
  [
    (set_background_mesh, "mesh_pic_report_screen"),
    (call_script, "script_get_player_party_morale_values"),
    (assign, ":party_size_modifier", "$g_player_party_morale_modifier_party_size"),
    (assign, ":leadership_modifier", "$g_player_party_morale_modifier_leadership"),
    (assign, ":food_modifier", "$g_player_party_morale_modifier_food"),
    (party_get_morale, ":current_morale", "p_main_party"),
    (try_begin),
      (lt, ":current_morale", 25),
      (str_store_string, s2, "@dangerously low"),
    (else_try),
      (lt, ":current_morale", 45),
      (str_store_string, s2, "@poor"),
    (else_try),
      (lt, ":current_morale", 65),
      (str_store_string, s2, "@steady"),
    (else_try),
      (lt, ":current_morale", 85),
      (str_store_string, s2, "@good"),
    (else_try),
      (str_store_string, s2, "@excellent"),
    (try_end),
    (try_begin),
      (gt, ":party_size_modifier", 20),
      (str_store_string, s3, "@The company is large enough that crowding and divided attention are wearing on discipline."),
    (else_try),
      (str_store_string, s3, "@Party size is not the main morale problem."),
    (try_end),
    (try_begin),
      (gt, ":leadership_modifier", 20),
      (str_store_string, s4, "@Leadership is doing real work to hold the company together."),
    (else_try),
      (str_store_string, s4, "@Leadership helps, but cannot solve every complaint alone."),
    (try_end),
    (try_begin),
      (gt, "$g_player_party_morale_modifier_no_food", 0),
      (str_store_string, s5, "@Food is an immediate grievance."),
    (else_try),
      (gt, ":food_modifier", 15),
      (str_store_string, s5, "@Food variety is helping spirits."),
    (else_try),
      (str_store_string, s5, "@Food is adequate, though nobody is singing about it."),
    (try_end),
    (try_begin),
      (gt, "$g_player_party_morale_modifier_debt", 0),
      (str_store_string, s6, "@Wage debt is souring the ranks."),
    (else_try),
      (str_store_string, s6, "@Wages are not causing open complaint."),
    (try_end),
    (str_store_string, s1, "@Company Morale Report^^Current party morale is {s2}.^^{s3}^{s4}^{s5}^{s6}"),
    ],
    [
      ("continue", [], "Continue...",
       [(jump_to_menu, "mnu_reports"),
        ]
       ),
      ]
  ),
# [ src/menus/0000_hardcoded_mb1011/character_report.py:L1-L165 ] character_report
("character_report", mnf_enable_hot_keys,
   "{s9}",
   "none",
   [
    (set_background_mesh, "mesh_pic_report_screen"),
    (try_begin),
      (gt, "$g_player_reading_book", 0),
      (player_has_item, "$g_player_reading_book"),
      (call_script, "script_sod_books_describe_current_reading_to_s20"),
      (str_store_string, s9, "@{s20}"),
    (else_try),
      (assign, "$g_player_reading_book", 0),
      (str_store_string, s9, "@No book is open beside your bedroll."),
    (try_end),
    (assign, ":num_friends", 0),
    (assign, ":num_enemies", 0),
    (str_store_string, s6, "@none"),
    (str_store_string, s8, "@none"),
    (try_for_range, ":troop_no", kingdom_heroes_begin, kingdom_heroes_end),
      (call_script, "script_troop_get_player_relation", ":troop_no"),
      (assign, ":player_relation", reg0),
      #(troop_get_slot, ":player_relation", ":troop_no", slot_troop_player_relation),
      (try_begin),
        (gt, ":player_relation", 20),
        (try_begin),
          (eq, ":num_friends", 0),
          (call_script, "script_store_troop_name", s8, ":troop_no"),
        (else_try),
          (eq, ":num_friends", 1),
          (call_script, "script_store_troop_name", s7, ":troop_no"),
          (str_store_string, s8, "@{s7} and {s8}"),
        (else_try),
          (call_script, "script_store_troop_name", s7, ":troop_no"),
          (str_store_string, s8, "@{s7}, {s8}"),
        (try_end),
        (val_add, ":num_friends", 1),
      (else_try),
        (lt, ":player_relation", -20),
        (try_begin),
          (eq, ":num_enemies", 0),
          (call_script, "script_store_troop_name", s6, ":troop_no"),
        (else_try),
          (eq, ":num_enemies", 1),
          (call_script, "script_store_troop_name", s5, ":troop_no"),
          (str_store_string, s6, "@{s5} and {s6}"),
        (else_try),
          (call_script, "script_store_troop_name", s5, ":troop_no"),
          (str_store_string, s6, "@{s5}, {s6}"),
        (try_end),
        (val_add, ":num_enemies", 1),
      (try_end),
    (try_end),
    (assign, ":honor_score", "$player_honor"),
    (troop_get_slot, ":player_renown", "trp_player", slot_troop_renown),
    (try_begin),
      (lt, ":player_renown", 100),
      (str_store_string, s2, "@little known"),
    (else_try),
      (lt, ":player_renown", 300),
      (str_store_string, s2, "@locally known"),
    (else_try),
      (lt, ":player_renown", 700),
      (str_store_string, s2, "@well known"),
    (else_try),
      (lt, ":player_renown", 1200),
      (str_store_string, s2, "@famous across the realm"),
    (else_try),
      (str_store_string, s2, "@spoken of everywhere"),
    (try_end),
    (try_begin),
      (lt, ":honor_score", -20),
      (str_store_string, s3, "@feared and distrusted"),
    (else_try),
      (lt, ":honor_score", 0),
      (str_store_string, s3, "@questionable"),
    (else_try),
      (lt, ":honor_score", 15),
      (str_store_string, s3, "@ordinary"),
    (else_try),
      (lt, ":honor_score", 40),
      (str_store_string, s3, "@respectable"),
    (else_try),
      (str_store_string, s3, "@widely honored"),
    (try_end),
    (try_begin), # SoD Twan : display badboy rating and decay when PSF is active
      (faction_slot_eq, "fac_player_supporters_faction", slot_faction_state, sfs_active),           
      (faction_get_slot, ":badboy_rating", "fac_player_supporters_faction", slot_faction_badboy_rating),
      (call_script, "script_calculate_badboy_decay"),
      (try_begin),
        (lt, ":badboy_rating", 10),
        (str_store_string, s4, "@barely noticed"),
      (else_try),
        (lt, ":badboy_rating", 30),
        (str_store_string, s4, "@muttered about"),
      (else_try),
        (lt, ":badboy_rating", 60),
        (str_store_string, s4, "@watched with suspicion"),
      (else_try),
        (str_store_string, s4, "@treated as a serious menace"),
      (try_end),
    (str_store_string, s9, "@Fame: {s2}.^Reputation: {s3}.^Political notoriety: {s4}.^^Friends: {s8}.^Enemies: {s6}.^{s9}"),
    (else_try),
    (str_store_string, s9, "@Fame: {s2}.^Reputation: {s3}.^^Friends: {s8}.^Enemies: {s6}.^{s9}"),
    (try_end),          # Sod Twan End

    (call_script, "script_get_number_of_hero_centers", "trp_player"),
    (assign, ":no_centers", reg0),
    (try_begin),
      (gt, ":no_centers", 0),
      (try_for_range, ":i_center", 0, ":no_centers"),
        (call_script, "script_troop_get_leaded_center_with_index", "trp_player", ":i_center"),
        (assign, ":cur_center", reg0),
        (try_begin),
          (eq, ":i_center", 0),
          (str_store_party_name, s8, ":cur_center"),
        (else_try),
          (eq, ":i_center", 1),
          (str_store_party_name, s7, ":cur_center"),
          (str_store_string, s8, "@{s7} and {s8}"),
        (else_try),
          (str_store_party_name, s7, ":cur_center"),
          (str_store_string, s8, "@{s7}, {s8}"),
        (try_end),
      (try_end),
      (str_store_string, s9, "@Your estates are: {s8}.^{s9}"),
    (try_end),
    (try_begin),
      (gt, "$players_kingdom", 0),
      (str_store_faction_name, s8, "$players_kingdom"),
      #MORDACHAI - tell them they're King, if they are...
      (try_begin),
        (faction_slot_eq, "$players_kingdom", slot_faction_leader, "trp_player"),
        (str_store_string, s9, "@You are the {King/Queen} of the {s8}.^{s9}"),
      (else_try),
        (try_begin),
          (eq, "$player_has_homage", 0),
          (store_current_day, ":day"),
          (store_sub, ":contract_days_left", "$mercenary_service_next_renew_day", ":day"),
          (try_begin),
            (le, ":contract_days_left", 3),
            (str_store_string, s7, "@will expire very soon"),
          (else_try),
            (le, ":contract_days_left", 10),
            (str_store_string, s7, "@has little time remaining"),
          (else_try),
            (str_store_string, s7, "@is still secure for now"),
          (try_end),
          (str_store_string, s9, "@Your kingdom mercenary service {s7}.^{s9}"),
        (try_end),
        (assign, reg0, "$player_has_homage"),
        (str_store_string, s9, "@You are a {reg0?lord of:mercenary for} the {s8}.^{s9}"),
      (try_end),
    (try_end),
    (call_script, "script_merc_describe_report_summary"),
    (str_store_string, s9, "@{s60}^{s61}^{s62}^{s9}"),
  ],
  [
    ("continue", [], "Continue...",
     [(jump_to_menu, "mnu_reports"),
      ]
     ),
    ]
  ),
# [ src/menus/0000_hardcoded_mb1011/party_size_report.py:L1-L112 ] party_size_report
("party_size_report", mnf_enable_hot_keys,
   "{s1}",
   "none",
   [
    (set_background_mesh, "mesh_pic_report_screen"),
    (call_script, "script_game_get_party_companion_limit"),
    (assign, ":party_size_limit", reg0),

    (store_skill_level, ":leadership", "skl_leadership", "trp_player"),
    (try_begin),
      (faction_slot_eq, "$players_kingdom", slot_faction_leader, "trp_player"),
      (val_mul, ":leadership", 2),
    (else_try),
      (gt, "$players_kingdom", 0),
      (neq, "$players_kingdom", "fac_player_supporters_faction"),
      (eq, "$player_has_homage", 0),
      (store_current_day, ":cur_day"),
      (gt, "$mercenary_service_next_renew_day", ":cur_day"),
      (val_mul, ":leadership", 2),
    (try_end),
    #MORDACHAI - Leadership counts x10 (was x5)
    (val_mul, ":leadership", 10),
    (store_attribute_level, ":charisma", "trp_player", ca_charisma),

    (troop_get_slot, ":renown", "trp_player", slot_troop_renown),
    (val_div, ":renown", 25),
    (try_begin),
      (gt, ":leadership", 0),
      (str_store_string, s2, "@ +"),
    (else_try),
      (str_store_string, s2, "@ "),
    (try_end),
    (try_begin),
      (gt, ":charisma", 0),
      (str_store_string, s3, "@ +"),
    (else_try),
      (str_store_string, s3, "@ "),
    (try_end),
    (try_begin),
      (gt, ":renown", 0),
      (str_store_string, s4, "@ +"),
    (else_try),
      (str_store_string, s4, "@ "),
    (try_end),
    (assign, reg5, ":party_size_limit"),
    (assign, reg1, ":leadership"),
    (assign, reg2, ":charisma"),
    (assign, reg3, ":renown"),
    (str_store_string, s1, "@Current party size limit is {reg5}.^Current party size modifiers are:^^Base size:  +10^Leadership: {s2}{reg1}^Charisma: {s3}{reg2}^Renown: {s4}{reg3}^TOTAL:  {reg5}"),

    (try_begin),
      (gt, "$players_kingdom", 0),
      (call_script, "script_sod_get_realm_military_centralization_profile", "$players_kingdom"),
      (assign, ":centralization", reg0),
      (assign, ":militarization", reg1),
      (assign, ":ruler_host_modifier", reg2),
      (assign, ":vassal_host_modifier", reg3),
      (assign, ":noble_happiness", reg4),
      (assign, ":unrest_pressure", reg5),
      (try_begin),
        (lt, ":centralization", 35),
        (str_store_string, s10, "@power is dispersed among the landed nobles"),
      (else_try),
        (lt, ":centralization", 70),
        (str_store_string, s10, "@the crown and nobles share military authority uneasily"),
      (else_try),
        (str_store_string, s10, "@military authority is concentrated near the crown"),
      (try_end),
      (try_begin),
        (lt, ":militarization", 35),
        (str_store_string, s11, "@realm levies remain lightly organized"),
      (else_try),
        (lt, ":militarization", 70),
        (str_store_string, s11, "@realm levies are reasonably organized"),
      (else_try),
        (str_store_string, s11, "@realm levies are heavily organized for war"),
      (try_end),
      (try_begin),
        (gt, ":ruler_host_modifier", ":vassal_host_modifier"),
        (str_store_string, s12, "@the ruler's host benefits more than the vassal estates"),
      (else_try),
        (gt, ":vassal_host_modifier", ":ruler_host_modifier"),
        (str_store_string, s12, "@vassal estate armies benefit more than the ruler's host"),
      (else_try),
        (str_store_string, s12, "@ruler and vassal hosts benefit about equally"),
      (try_end),
      (try_begin),
        (lt, ":noble_happiness", 35),
        (str_store_string, s13, "@noble patience is wearing thin"),
      (else_try),
        (gt, ":unrest_pressure", 65),
        (str_store_string, s13, "@unrest is beginning to tax the system"),
      (else_try),
        (str_store_string, s13, "@the nobility can live with the current arrangement"),
      (try_end),
      (try_begin),
        (faction_slot_eq, "$players_kingdom", slot_faction_leader, "trp_player"),
        (str_store_string, s1, "@{s1}^^Realm military law:^Authority: {s10}.^Levy system: {s11}.^Host balance: {s12}.^Political mood: {s13}.^^As ruler, centralization concentrates military support around your own host. Decentralization strengthens your vassals' estate armies."),
      (else_try),
        (str_store_string, s1, "@{s1}^^Realm military law:^Authority: {s10}.^Levy system: {s11}.^Host balance: {s12}.^Political mood: {s13}.^^As a vassal, centralization pulls military support toward the crown. Decentralization gives landed nobles more room to raise estate armies."),
      (try_end),
    (try_end),
    ],
    [
      ("continue", [], "Continue...",
       [(jump_to_menu, "mnu_reports"),
        ]
       ),
      ]
  ),
# [ src/menus/0000_hardcoded_mb1011/faction_relations_report.py:L1-L48 ] faction_relations_report
("faction_relations_report", mnf_enable_hot_keys,
   "{s1}",
   "none",
   [
    (set_background_mesh, "mesh_pic_report_screen"),
    (str_clear, s2),
    (try_for_range, ":cur_kingdom", kingdoms_begin, kingdoms_end),
      (faction_slot_eq, ":cur_kingdom", slot_faction_state, sfs_active),
      (neq, ":cur_kingdom", "fac_player_supporters_faction"),
      (store_relation, ":cur_relation", "fac_player_supporters_faction", ":cur_kingdom"),
      (call_script, "script_get_realtion_name_s3", ":cur_relation"),
      (str_store_faction_name, s4, ":cur_kingdom"),
      (str_store_string, s2, "@{s2}^{s4}: {s3}"),
    (try_end),
	
	(str_clear, s5), # SoD Twan display truces
    (store_current_day, ":cur_day"),
		(try_for_range, ":slot_no", faction_truce_slots_begin, faction_truce_slots_end),                                 
		(faction_get_slot, ":truce_day", "fac_player_supporters_faction", ":slot_no"),
		(try_begin),
		(gt, ":truce_day", ":cur_day"),
		(store_sub, ":truce_days_remaining", ":truce_day", ":cur_day"),
		(store_sub, ":kingdom_no", ":slot_no", faction_truce_slots_begin),
		(val_add, ":kingdom_no", "fac_player_supporters_faction"),
		(str_store_faction_name, s6, ":kingdom_no"),
    (try_begin),
      (lt, ":truce_days_remaining", 7),
      (str_store_string, s7, "@nearly expired"),
    (else_try),
      (lt, ":truce_days_remaining", 21),
      (str_store_string, s7, "@still recent"),
    (else_try),
      (str_store_string, s7, "@secure for now"),
    (try_end),
		(str_store_string, s5, "@{s5}You have a peace agreement with {s6}; it is {s7}.^"),
		(try_end),
		(try_end),
    (str_store_string, s1, "@Your relation with the factions are:^{s2}^^{s5}"),                           # SoD twan end
    ],
    [
      ("continue", [], "Continue...",
       [(jump_to_menu, "mnu_reports"),
        ]
       ),
      ]
  ),
# [ src/menus/0000_hardcoded_mb1011/guilds_relations_report.py:L1-L30 ] guilds_relations_report
("guilds_relations_report", mnf_enable_hot_keys,
   "{s1}",
   "none",
   [
    (set_background_mesh, "mesh_pic_report_screen"),
    (store_relation, ":cur_relation", "fac_player_supporters_faction", "fac_commoners"),
    (call_script, "script_get_realtion_name_s3", ":cur_relation"),
    (assign, reg1, ":cur_relation"),
    (str_store_string, s2, "@^The Commoners: {reg1} ({s3})"),
    (try_for_range, ":cur_kingdom", guilds_begin, guilds_end),
      (store_relation, ":cur_relation", "fac_player_supporters_faction", ":cur_kingdom"),
      (call_script, "script_get_realtion_name_s3", ":cur_relation"),
      (str_store_faction_name, s4, ":cur_kingdom"),
      (call_script, "script_merc_describe_guild_progression", ":cur_kingdom"),
      (call_script, "script_sod_merc_guild_describe_ledger_to_s20", ":cur_kingdom"),
      (assign, reg1, ":cur_relation"),
      (str_store_string, s2, "@{s2}^{s4}: {reg1} ({s3}) - {s64} {s65} {s66}^{s20}"),
    (try_end),

    (str_store_string, s1, "@A tally of your standing with the guilds:^^Progression guide: promotion at 10, elite access by guild, special service at 30, trusted favor at 40.^{s2}"),                           # SoD twan end
    ],
    [
      ("continue", [], "Return to the reports...",
       [(jump_to_menu, "mnu_reports"),
        ]
       ),
      ]
  ),
