# [ src/menus/0000_hardcoded_mb1011/camp_action_read_book_start.py:L1-L26 ] camp_action_read_book_start
("camp_action_read_book_start", mnf_scale_picture|mnf_enable_hot_keys,
   "{s1}",
   "none",
   [
    (set_background_mesh, "mesh_pic_camp"),
    (assign, ":new_book", "$temp"),
    (str_store_item_name, s2, ":new_book"),
    (try_begin),
      (store_attribute_level, ":int", "trp_player", ca_intelligence),
      (item_get_slot, ":int_req", ":new_book", slot_item_intelligence_requirement),
      (le, ":int_req", ":int"),
      (call_script, "script_sod_books_describe_book_to_s20", ":new_book"),
      (str_store_string, s1, "@You start reading {s2}.^^{s20}^^After a few pages, the book begins making demands of you. You keep it close by, to be read in stolen hours: beside watchfires, inside taverns, and during the long pauses where armies pretend they are resting."),
      (assign, "$g_player_reading_book", ":new_book"),
    (else_try),
      (str_store_string, s1, "@You flip through the pages of {s2}, but you find the text confusing and difficult to follow. Try as you might, it soon gives you a headache, and you're forced to give up the attempt."),
    (try_end), ],
    [
      ("continue", [], "Continue...",
       [(jump_to_menu, "mnu_camp"),
        ]
       ),
      ]
  ),
# [ src/menus/0000_hardcoded_mb1011/retirement_verify.py:L1-L23 ] retirement_verify
("retirement_verify", mnf_scale_picture|mnf_enable_hot_keys,
   "You are at day {reg0}. Your current luck is {reg1}.^^Are you sure you want to retire?",
   "none",
    [
      (set_background_mesh, "mesh_pic_defeat"),
      (store_current_day, reg0),
      (assign, reg1, "$g_player_luck"),
    ],
    [
      ("retire_yes", [], "Yes.",
        [
          (start_presentation, "prsnt_retirement"),
        ]
      ),
      ("retire_no", [], "No.",
        [
         (jump_to_menu, "mnu_camp"),
        ]
      ),
    ]
  ),
# [ src/menus/0000_hardcoded_mb1011/quick_start.py:L1-L50 ] quick_start
("quick_start", mnf_scale_picture|mnf_enable_hot_keys,
   "You are currently level {reg8}.  You have {reg5} renown, {reg3} honor, and {reg4} denars.^You have used {reg6} cheats in this game.^^{s1}",
   "none",
   [
    (set_background_mesh, "mesh_pic_payment"),

    (store_character_level, reg8, "trp_player"),
    # generate a list of your hero companions and their current levels.
    (party_get_num_companion_stacks, ":i", "p_main_party"),
    (assign, ":count", 0),
    (str_store_string, s2, "@Nobody"),
    (try_for_range, ":stack_no", 0, ":i"),
      (party_stack_get_troop_id, ":troop_id", "p_main_party", ":stack_no"),
      (is_between, ":troop_id", companions_begin, companions_end),
      # get the companion's name and level
      (call_script, "script_store_troop_name", s1, ":troop_id"),
      (store_character_level, reg1, ":troop_id"),
      (str_store_string, s1, "@{s1} (lvl {reg1})"),
      # build up the list from right to left
      (try_begin),
        (eq, ":count", 0),
        (str_store_string, s2, "@{s1}"),
      (else_try),
        (eq, ":count", 1),
        (str_store_string, s2, "@{s1} and {s2}"),
      (else_try),
        (str_store_string, s2, "@{s1}, {s2}"),
      (try_end),
      (val_add, ":count", 1),
    (try_end),
    (str_store_string, s1, "@You are travelling with: {s2}"),
    (troop_get_slot, reg5, "trp_player", slot_troop_renown),
    (assign, reg3, "$player_honor"),
    (store_troop_gold, reg4, "trp_player"),
	(assign, reg6, "$g_sod_cheat_mode_used"),
   ],
   [
    ("get_npcs", [], "Add companions to my party...", [(assign, "$inventory_menu_offset", 0), (jump_to_menu, "mnu_add_companions")]),
    ("give_xp", [(eq, "$g_sod_cheat_mode", 1), (store_character_level, reg1, "trp_player"), (val_mul, reg1, 500)], "Give me {reg1} XP.", [(add_xp_as_reward, reg1), (val_add,"$g_sod_cheat_mode_used", 1)]), #twan456
    ("give_denars", [(eq, "$g_sod_cheat_mode", 1)], "Give me 5000 denars.", [(call_script, "script_troop_add_gold", "trp_player", 5000), (val_add,"$g_sod_cheat_mode_used", 1)]),
    ("give_renown", [(eq, "$g_sod_cheat_mode", 1)], "Give me 50 renown.", [(call_script, "script_change_troop_renown", "trp_player", 50), (val_add,"$g_sod_cheat_mode_used", 1)]),
    ("give_honor", [(eq, "$g_sod_cheat_mode", 1)], "Give me 10 honor.", [(call_script, "script_change_player_honor", 10), (val_add,"$g_sod_cheat_mode_used", 1)]), #twan456
    ("take_honor", [], "Strip me of 10 honor.", [(call_script, "script_change_player_honor", -10)]),
    ("rechoose_banner", [], "Choose a different banner...", [(jump_to_menu, "mnu_banner_selection")]),
    ("quick_start_oracle", [(eq, "$g_sod_cheat_mode", 1)], "Consult oracle...", [(jump_to_menu, "mnu_quick_start_oracle"), (val_add, "$g_sod_cheat_mode_used", 1)]),
    ("done", [], "I think that ought to just about do it!", [(jump_to_menu, "mnu_camp")]),
   ]
  ),
# [ src/menus/0000_hardcoded_mb1011/quick_start_oracle.py:L1-L48 ] quick_start_oracle
("quick_start_oracle", mnf_scale_picture|mnf_enable_hot_keys,
   "{s1}",
   "none",
   [
    (set_background_mesh, "mesh_pic_payment"),
    (store_current_day, ":today"),
    (store_sub, ":days_left", "$g_sod_invasion_begin", ":today"),
    (try_begin),
      (lt, ":today", "$g_sod_invasion_begin"),
      (try_begin),
        (le, ":days_left", 20),
        (str_store_string, s1, "@The invasion is close enough to taste iron in the wind..."),
      (else_try),
        (le, ":days_left", 60),
        (str_store_string, s1, "@The invasion is not immediate, but the road to it is short..."),
      (else_try),
        (str_store_string, s1, "@The invasion is still distant enough for preparation, if you do not waste the warning..."),
      (try_end),
      (assign, reg9, 0),
    (else_try),
      (str_store_string, s1, "@It has already begun! Dun, dun, dun!"),
      (assign, reg9, 1),
    (try_end),
   ],
   [
    ("invade_sooner", [(store_current_day, ":today"), (lt, ":today", "$g_sod_invasion_begin")],
      "That's too far away!  Make it sooner.",
      [
        (val_sub, "$g_sod_invasion_begin", 30),
        (store_current_day, ":today"),
        (store_add, ":tomorrow", ":today", 1),
        (val_max, "$g_sod_invasion_begin", ":tomorrow"),
      ]),

    ("invade_later", [(store_current_day, ":today"), (lt, ":today", "$g_sod_invasion_begin")],
      "What?!  I'm not nearly ready yet!  Make it later.",
      [(val_add, "$g_sod_invasion_begin", 30), (val_add, "$g_sod_cheat_mode_used", 1)]),

    ("invade_done", [(store_current_day, ":today"), (lt, ":today", "$g_sod_invasion_begin")],
      "I must return to my prepartions...",
      [(jump_to_menu, "mnu_quick_start")]),

    ("invade_too_late", [(store_current_day, ":today"), (ge, ":today", "$g_sod_invasion_begin")],
      "I knew that!", [(jump_to_menu, "mnu_quick_start")]),
   ]
  ),
# [ src/menus/0000_hardcoded_mb1011/add_companions.py:L1-L137 ] add_companions
("add_companions", mnf_scale_picture|mnf_enable_hot_keys,
   "{s1}.^^Who would you like to add?",
   "none",
    [
      (set_background_mesh, "mesh_pic_payment"),
      # generate a list of your hero companions and their current levels.
      (party_get_num_companion_stacks, ":i", "p_main_party"),
      (assign, ":count", 0),
      (str_store_string, s2, "@Nobody"),
      (try_for_range, ":stack_no", 0, ":i"),
        (party_stack_get_troop_id, ":troop_id", "p_main_party", ":stack_no"),
        (is_between, ":troop_id", companions_begin, companions_end),
        # get the companion's name and level
        (call_script, "script_store_troop_name", s1, ":troop_id"),
        (store_character_level, reg1, ":troop_id"),
        (str_store_string, s1, "@{s1} (lvl {reg1})"),
        # build up the list from right to left
        (try_begin),
          (eq, ":count", 0),
          (str_store_string, s2, "@{s1}"),
        (else_try),
          (str_store_string, s2, "@{s1}^{s2}"),
        (try_end),
        (val_add, ":count", 1),
      (try_end),
      (str_store_string, s1, "@You are travelling with:^{s2}"),

      # generate the list of heros that aren't currently in your party, and let the player select them
      # concept & basic code ripped from - Fisheye's Autoloot -
      (assign, reg11, 0),
      (assign, reg12, 0),
      (assign, reg13, 0),
      (assign, reg14, 0),
      (assign, reg15, 0),
      (assign, reg16, 0),

      # count the number of available companions
      (assign, reg10, 0),
      (try_for_range, ":companion", companions_begin, companions_end),
        (troop_slot_eq, ":companion", slot_troop_occupation, 0),
        (val_add, reg10, 1),
      (try_end),

      # fall back a page if the current page no longer exists
      (try_begin),
        (eq, "$inventory_menu_offset", reg10),
        (val_sub, "$inventory_menu_offset", 6),
        (val_max, "$inventory_menu_offset", 0),
      (try_end),

      (assign, reg10, 0),
      (try_for_range, ":companion", companions_begin, companions_end),
        # only include heros that aren't currently a part of our party
        (troop_slot_eq, ":companion", slot_troop_occupation, 0),
        # count the number of such heros, and keep track of our current index into them
        (val_add, reg10, 1),
        (try_begin),
          (store_add, ":menu_index", "$inventory_menu_offset", 1),
          (eq, reg10, ":menu_index"),
          (assign, reg11, ":companion"),
          (call_script, "script_store_troop_name", 11, ":companion"),
        (else_try),
          (store_add, ":menu_index", "$inventory_menu_offset", 2),
          (eq, reg10, ":menu_index"),
          (assign, reg12, ":companion"),
          (call_script, "script_store_troop_name", 12, ":companion"),
        (else_try),
          (store_add, ":menu_index", "$inventory_menu_offset", 3),
          (eq, reg10, ":menu_index"),
          (assign, reg13, ":companion"),
          (call_script, "script_store_troop_name", 13, ":companion"),
        (else_try),
          (store_add, ":menu_index", "$inventory_menu_offset", 4),
          (eq, reg10, ":menu_index"),
          (assign, reg14, ":companion"),
          (call_script, "script_store_troop_name", 14, ":companion"),
        (else_try),
          (store_add, ":menu_index", "$inventory_menu_offset", 5),
          (eq, reg10, ":menu_index"),
          (assign, reg15, ":companion"),
          (call_script, "script_store_troop_name", 15, ":companion"),
        (else_try),
          (store_add, ":menu_index", "$inventory_menu_offset", 6),
          (eq, reg10, ":menu_index"),
          (assign, reg16, ":companion"),
          (call_script, "script_store_troop_name", 16, ":companion"),
        (try_end),
      (try_end),
      # reg10 now contains total num of heroes available to interact with (not yet in party)

      (store_add, reg1, "$inventory_menu_offset", 1),
      (store_add, reg2, "$inventory_menu_offset", 6),
      (val_min, reg2, reg10),
      (str_store_string, s1, "@{s1}^^(showing {reg1} through {reg2} of {reg10})"),
    ],
    [
      ("npc_1", [(gt, reg11, 0)], "{s11}", [(call_script, "script_setup_troop_meeting", reg11, 0)]),
      ("npc_2", [(gt, reg12, 0)], "{s12}", [(call_script, "script_setup_troop_meeting", reg12, 0)]),
      ("npc_3", [(gt, reg13, 0)], "{s13}", [(call_script, "script_setup_troop_meeting", reg13, 0)]),
      ("npc_4", [(gt, reg14, 0)], "{s14}", [(call_script, "script_setup_troop_meeting", reg14, 0)]),
      ("npc_5", [(gt, reg15, 0)], "{s15}", [(call_script, "script_setup_troop_meeting", reg15, 0)]),
      ("npc_6", [(gt, reg16, 0)], "{s16}", [(call_script, "script_setup_troop_meeting", reg16, 0)]),
      ("npc_next",
        [
          #base for next page
          (store_add, ":next_page", "$inventory_menu_offset", 6),
          (try_begin),
            # don't give this option if we're on the last page
            (ge, ":next_page", reg10),
            (disable_menu_option),
          (try_end),
        ],
        "[Next page]",
        [
          (val_add, "$inventory_menu_offset", 6),
          (jump_to_menu, "mnu_add_companions"),
        ]
      ),
      ("npc_previous",
        [
          (try_begin),
            # don't give this option if we're on the first page
            (eq, "$inventory_menu_offset", 0),
            (disable_menu_option),
          (try_end),
        ],
        "[Previous page]",
        [
          (val_sub, "$inventory_menu_offset", 6),
          (jump_to_menu, "mnu_add_companions"),
        ]
      ),
      ("npc_nvm", [], "That's enough companions, thanks.", [(jump_to_menu, "mnu_quick_start")]),
    ]
  ),
