# [ src/menus/captivity/captivity_castle_check.py:L1-L81 ] captivity_castle_check
(
    "captivity_castle_check", 0,
    "You wait in the damp darkness of the keep while your captors decide your fate.",
    "none",
    [
        (troop_get_type, ":is_female", "trp_player"),
        (try_begin),
          (eq, ":is_female", 1),
          (set_background_mesh, "mesh_pic_prisoner_fem"),
        (else_try),
          (set_background_mesh, "mesh_pic_prisoner_man"),
        (try_end),
        (assign, ":capturer_faction", "fac_outlaws"),
        (call_script, "script_sod_validate_capturer_party_to_reg"),
        (try_begin),
          (eq, reg0, 1),
          (store_faction_of_party, ":capturer_faction", "$capturer_party"),
        (try_end),
        (store_character_level, ":player_level", "trp_player"),
        (troop_get_slot, ":renown", "trp_player", slot_troop_renown),
        (store_div, ":renown_factor", ":renown", 100),
        (assign, ":ransom_chance", 45),
        (assign, ":exchange_chance", 25),
        (assign, ":remain_chance", 30),
        (store_random_in_range, "$player_ransom_amount", 4, 7),
        (val_mul, "$player_ransom_amount", 100),
        (try_begin),
          (eq, ":capturer_faction", "fac_sod_merc_guild6"),
          (call_script, "script_sod_slavers_apply_player_action", sod_slaver_action_captivity, 4),
          (call_script, "script_sod_slavers_update_market_state"),
          (faction_get_slot, ":slaver_demand", "fac_sod_merc_guild6", slot_faction_slaver_market_demand),
          (faction_get_slot, ":slaver_supply", "fac_sod_merc_guild6", slot_faction_slaver_market_supply),
          (faction_get_slot, ":slaver_heat", "fac_sod_merc_guild6", slot_faction_slaver_market_heat),
          (store_div, ":demand_pressure", ":slaver_demand", 10),
          (val_add, ":ransom_chance", ":demand_pressure"),
          (store_div, ":heat_pressure", ":slaver_heat", 15),
          (val_add, ":remain_chance", ":heat_pressure"),
          (store_mul, ":market_discount", ":slaver_supply", 2),
          (val_sub, "$player_ransom_amount", ":market_discount"),
          (val_max, "$player_ransom_amount", 200),
        (try_end),
        (store_mul, ":level_fee", ":player_level", 35),
        (val_add, "$player_ransom_amount", ":level_fee"),
        (store_mul, ":renown_fee", ":renown_factor", 60),
        (val_add, "$player_ransom_amount", ":renown_fee"),
        (try_begin),
          (eq, "$g_sod_king", 1),
          (val_add, "$player_ransom_amount", 600),
          (val_add, ":ransom_chance", 10),
          (val_add, ":remain_chance", 5),
        (try_end),
        (try_begin),
          (gt, "$player_honor", 20),
          (val_add, ":exchange_chance", 10),
          (val_sub, ":remain_chance", 5),
        (else_try),
          (lt, "$player_honor", -20),
          (val_add, ":remain_chance", 10),
          (val_sub, ":exchange_chance", 5),
        (try_end),
        (val_clamp, ":ransom_chance", 10, 81),
        (val_clamp, ":exchange_chance", 5, 71),
        (val_clamp, ":remain_chance", 5, 81),
        (store_random_in_range, reg(7), 0, 100),
        (try_begin),
          (lt, reg(7), ":ransom_chance"),
          (store_troop_gold, reg(3), "trp_player"),
          (gt, reg(3), "$player_ransom_amount"),
          (jump_to_menu, "mnu_captivity_end_propose_ransom"),
        (else_try),
          (store_add, ":exchange_threshold", ":ransom_chance", ":exchange_chance"),
          (lt, reg(7), ":exchange_threshold"),
          (jump_to_menu, "mnu_captivity_end_exchanged_with_prisoner"),
        (else_try),
          (jump_to_menu, "mnu_captivity_castle_remain"),
        (try_end),
    ],
    []
  ),
