		  (val_add, ":p_size", 1),
		  (store_random_in_range, ":rand", ":plyr_lvl", ":p_size"),
		  (str_store_troop_name_by_count, s35, ":bandit_troop", ":rand"),
		  (assign, reg8, ":rand"),
