# [ src/menus/start_game/peasant_start_practice.py:L1-L40 ] train_peasants_against_bandits_ready
(
    "train_peasants_against_bandits_ready", 0,
    "You put the peasants through the basics of soldiering, discipline and obedience. You think {reg0} of them {reg1?have:has} fully grasped the training and {reg1?are:is} ready for some practice.",
    "none",
    [
      (store_character_level, ":level", "trp_player"),
      (val_div, ":level", 10),
      (val_add, ":level", 1),
      (quest_get_slot, ":quest_target_amount", "qst_train_peasants_against_bandits", slot_quest_target_amount),
      (quest_get_slot, ":quest_current_state", "qst_train_peasants_against_bandits", slot_quest_current_state),
      (val_sub, ":quest_target_amount", ":quest_current_state"),
      (assign, ":max_random", ":level"),
      (val_min, ":max_random", ":quest_target_amount"),
      (val_add, ":max_random", 1),
      (store_random_in_range, ":random_number", 1, ":max_random"),
      (assign, "$g_train_peasants_against_bandits_num_peasants", ":random_number"),
      (assign, reg0, ":random_number"),
      (store_sub, reg1, ":random_number", 1),
      (str_store_troop_name_by_count, s0, "trp_trainee_peasant", ":random_number"),
     ],
    [
      ("peasant_start_practice", [], "Start the practice fight.",
       [
         (set_jump_mission, "mt_village_training"),
         (quest_get_slot, ":target_center", "qst_train_peasants_against_bandits", slot_quest_target_center),
         (party_get_slot, ":village_scene", ":target_center", slot_castle_exterior),
         (modify_visitors_at_site, ":village_scene"),
         (reset_visitors),
         (set_visitor, 0, "trp_player"),
         (set_visitors, 1, "trp_trainee_peasant", "$g_train_peasants_against_bandits_num_peasants"),
         (set_jump_entry, 11),
         (jump_to_scene, ":village_scene"),
         (jump_to_menu, "mnu_train_peasants_against_bandits_training_result"),
         (music_set_situation, 0),
         (change_screen_mission),
         ]),
      ]
    ),
# [ src/menus/start_game/start_collecting.py:L1-L117 ] collect_taxes
(
    "collect_taxes", mnf_disable_all_keys,
    "{reg3?You expect:{s1} expects} the tax collection to take {s2}.",
    "none",
    [
      (set_background_mesh, "$g_sod_town_background"),

      (call_script, "script_get_max_skill_of_player_party", "skl_trade"),
      (assign, ":max_skill", reg0),
      (assign, reg2, reg0),
      (assign, ":max_skill_owner", reg1),
      (try_begin),
        (eq, ":max_skill_owner", "trp_player"),
        (assign, reg3, 1),
      (else_try),
        (assign, reg3, 0),
        (call_script, "script_store_troop_name", s1, ":max_skill_owner"),
      (try_end),
      (assign, ":tax_quest_expected_revenue", 3000),
      (try_begin),
        (party_slot_eq, "$current_town", slot_party_type, spt_town),
        (assign, ":tax_quest_expected_revenue", 6000),
      (try_end),
      (call_script, "script_sod_get_center_population_capacity_profile", "$current_town"),
      (assign, ":tax_capacity_pct", reg3),
      (assign, ":productive_population", reg9),
      (val_mul, ":tax_quest_expected_revenue", ":tax_capacity_pct"),
      (val_div, ":tax_quest_expected_revenue", 100),
      (try_begin),
        (gt, ":productive_population", 0),
        (val_max, ":tax_quest_expected_revenue", 50),
      (try_end),

      (try_begin),
       (quest_slot_eq, "qst_collect_taxes", slot_quest_current_state, 0),
       (store_add, ":max_skill_plus_thirty", ":max_skill", 30),
       (try_begin),
         (party_slot_eq, "$current_town", slot_party_type, spt_town),
         (store_div, "$qst_collect_taxes_total_hours", 24* 7 * 30, ":max_skill_plus_thirty"),
       (else_try),
         #Village
         (store_div, "$qst_collect_taxes_total_hours", 24 * 3 * 30, ":max_skill_plus_thirty"),
       (try_end),

       (call_script, "script_party_count_fit_for_battle", "p_main_party"),
       (val_add, reg0, 20),
       (val_mul, "$qst_collect_taxes_total_hours", 20),
       (val_div, "$qst_collect_taxes_total_hours", reg0),
       (try_begin),
         (lt, ":tax_capacity_pct", 100),
         (store_sub, ":tax_capacity_drag", 100, ":tax_capacity_pct"),
         (val_div, ":tax_capacity_drag", 2),
         (val_add, ":tax_capacity_drag", 100),
         (val_mul, "$qst_collect_taxes_total_hours", ":tax_capacity_drag"),
         (val_div, "$qst_collect_taxes_total_hours", 100),
       (try_end),

       (quest_set_slot, "qst_collect_taxes", slot_quest_target_amount, "$qst_collect_taxes_total_hours"),
       (store_div, ":menu_begin_time", "$qst_collect_taxes_total_hours", 20), #between %5-%25
       (store_div, ":menu_end_time", "$qst_collect_taxes_total_hours", 4),
       (assign, ":unrest_begin_time", ":menu_end_time"), #between %25-%75
       (store_mul, ":unrest_end_time", "$qst_collect_taxes_total_hours", 3),
       (val_div, ":unrest_end_time", 4),

       (val_mul, ":tax_quest_expected_revenue", 2),
       (store_div, "$qst_collect_taxes_hourly_income", ":tax_quest_expected_revenue", "$qst_collect_taxes_total_hours"),

       (store_random_in_range, "$qst_collect_taxes_menu_counter", ":menu_begin_time", ":menu_end_time"),
       (store_random_in_range, "$qst_collect_taxes_unrest_counter", ":unrest_begin_time", ":unrest_end_time"),
       (assign, "$qst_collect_taxes_halve_taxes", 0),
      (try_end),
      (quest_get_slot, ":target_hours", "qst_collect_taxes", slot_quest_target_amount),
      (store_div, ":target_days", ":target_hours", 24),
      (val_mul, ":target_days", 24),
      (try_begin),
        (lt, ":target_days", ":target_hours"),
        (val_add, ":target_days", 24),
      (try_end),
      (val_div, ":target_days", 24),
      (assign, reg4, ":target_days"),
      (try_begin),
        (le, ":target_days", 1),
        (str_store_string, s2, "@about a day if the locals cooperate"),
      (else_try),
        (le, ":target_days", 3),
        (str_store_string, s2, "@a few days"),
      (else_try),
        (le, ":target_days", 7),
        (str_store_string, s2, "@most of a week"),
      (else_try),
        (str_store_string, s2, "@a long and unpopular week or more"),
      (try_end),
    ],
    [
      ("start_collecting", [], "Start collecting.",
       [(assign, "$qst_collect_taxes_currently_collecting", 1),
        (try_begin),
          (quest_slot_eq, "qst_collect_taxes", slot_quest_current_state, 0),
          (quest_set_slot, "qst_collect_taxes", slot_quest_current_state, 1),
        (try_end),
        (rest_for_hours_interactive, 1000, 5, 0), #rest while not attackable
        (assign, "$auto_enter_town", "$current_town"),
        (assign, "$g_town_visit_after_rest", 1),
        (change_screen_return),
        ]),
      ("collect_later", [], "Put it off until later.",
       [(try_begin),
          (party_slot_eq, "$current_town", slot_party_type, spt_town),
          (jump_to_menu, "mnu_town"),
        (else_try),
          (jump_to_menu, "mnu_village"),
        (try_end),
        ]),
    ]
  ),
# [ src/menus/centers/town/sod_merc_guild.py:L1-L61 ] sod_merc_guild
("sod_merc_guild",mnf_disable_all_keys,
  "You approach a mercenary base. Drill sergeants bark orders over the ring of steel, and armed sellswords watch you from the yard as they weigh your purpose here.",
  "none",[
  ],
    [
      ("enter",[],"Step into the yard.",[
	  (assign, "$g_sod_from_menu", 0),
	  (party_get_slot, ":base_scene", "$g_encountered_party", slot_castle_exterior),
	   (assign, "$g_mt_mode", abm_visit),
	   
          (scene_set_slot, ":base_scene", slot_scene_visited, 1),
       (set_jump_mission, "mt_mercenary_base"),
	   (call_script, "script_init_mercenary_base_walkers", ":base_scene"),
	   (jump_to_scene,":base_scene"),(change_screen_mission)],
	   "Door to the courtyard.",
	   ),
	   
	   
      ("office",[
	  (this_or_next|eq, "$g_encountered_party", "p_sod_merc_guild_1"),
	  (this_or_next|eq, "$g_encountered_party", "p_sod_merc_guild_2"),
	  (this_or_next|eq, "$g_encountered_party", "p_sod_merc_guild_3"),
	  (this_or_next|eq, "$g_encountered_party", "p_sod_merc_guild_4"),
	  (eq, "$g_encountered_party", "p_sod_merc_guild_5"),
      ],"Visit the guild master's office.",[
		(assign, "$g_sod_from_menu", -1),
		(party_get_slot, ":base_scene", "$g_encountered_party", slot_town_castle),
		(assign, "$g_mt_mode", abm_visit),
        (scene_set_slot, ":base_scene", slot_scene_visited, 1),
		(set_jump_mission, "mt_mercenary_base_interior"),
		(call_script, "script_init_mercenary_base_walkers", ":base_scene"),
		(jump_to_scene,":base_scene"),(change_screen_mission)],
	   "Door to Guild Master's office.",
	   ),
	   
	   ("talk", [],"Seek an audience with the guild master.", [
		(assign, "$g_sod_from_menu", -1),
       (party_get_slot, ":base_scene", "$g_encountered_party", slot_castle_exterior),
	   (assign, "$g_mt_mode", abm_visit),
       (set_jump_mission, "mt_mercenary_base_talk_to_guild_master"),
	   (store_sub, ":guild_master", "$g_encountered_party", "p_sod_merc_guild_1"),
	   (val_add, ":guild_master", "trp_black_army_guild_master"),
	   (assign, "$g_talk_troop", ":guild_master"),
	   (jump_to_scene,":base_scene"),
	   (change_screen_mission),
		 ]),
	   
	  ("upgrade", [
		 ],
        "Review your soldiers for promotion.",
        [
		  (assign, "$jump_menu", "mnu_sod_merc_guild"),
          (jump_to_menu, "mnu_sod_upgrade"),
        ]
      ),
      
	  ("leave",[],"Leave.",[(leave_encounter),(change_screen_return)]),
    ]
  ),
