          (quest_set_slot, "qst_companion_artimenner_siege_that_should", slot_quest_sod_runtime_metadata, "$g_sod_artimenner_siege_result_grade"),
          (call_script, "script_sod_companion_shift_approval", "trp_npc15", -2),
